begin;
with j as (select * from jsonb_to_recordset($law7d0027$[{"code_id":"BK_RF","article_number":"47.2","version_date":"1998-07-31","article_text":"1. Платежи в бюджет,  не уплаченные в установленный срок (задолженность по платежам в бюджет) ,  признаются безнадежными к взысканию в случае:\n\n1)  смерти физического лица - плательщика платежей в бюджет или объявления его умершим в порядке,  установленном гражданским процессуальным законодательством Российской Федерации;\n\n2)  завершения процедуры банкротства гражданина,  индивидуального предпринимателя в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве) \" - в части задолженности по платежам в бюджет,  от и\n\nерации об административных правонарушениях,  в случае,  если постановления о наложении административных штрафов вынесены мировыми судьями,  комиссиями по делам несовершеннолетних и защите их прав,  подлежат зачислению (если иное не установлено пунктами 3,  5 - 52 и 6 настоящей статьи) : (В редакции федеральных законов от 31.07.2020 № 263-ФЗ,  от 01.07.2021 № 244-ФЗ)\n\n1)  в бюджет субъекта Российской Федерации по нормативу 50 процентов;\n\n2)  в бюджет муниципального района,  муниципального округа,  городского округа,  городского округа с внутригородским делением (по месту нахождения органа или должностного лица,  принявших решение о наложении административного штрафа)  по нормативу 50 процентов. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\n5. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные должностными лицами органов муниципального контроля,  подлежат зачислению в бюджеты муниципальных образований,  за счет средств бюджетов которых осуществляется финансовое обеспечение деятельности указанных органов,  по нормативу 100 процентов.\n\n51. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные должностными лицами государственных внебюджетных фондов,  подлежат зачислению в бюджеты соответствующих внебюджетных фондов по нормативу 100 процентов. (Дополнение пунктом - Федеральный закон от 31.07.2020 № 263-ФЗ)\n\n52. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные инспекторами Счетной палаты Российской Федерации,  должностными лицами контрольно-счетных органов субъектов Российской Федерации,  подлежат зачислению соответственно в федеральный бюджет,  бюджеты субъектов Российской Федерации по нормативу 100 процентов (если иное не установлено пунктом 6 настоящей статьи) . (Дополнение пунктом - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\n53. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения,  выявленные исполнительными органами субъектов Российской Федерации,  осуществляющими государственный надзор за состоянием,  содержанием,  сохранением,  использованием,  популяризацией и государственной охраной объектов культурного наследия,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов (если иное не установлено пунктом 4 настоящей статьи) . (Дополнение пунктом - Федеральный закон от 24.06.2025 № 158-ФЗ)\n\n6. Суммы штрафов,  установленных Кодексом Российской Федерации об административных правонарушениях за административные правонарушения в области финансов,  связанные с нецелевым использованием бюджетных средств,  невозвратом либо несвоевременным возвратом бюджетного кредита,  неперечислением либо несвоевременным перечислением платы за пользование бюджетным кредитом,  нарушением условий предоставления бюджетного кредита,  нарушением порядка и (или)  условий предоставления (расходования)  межбюджетных трансфертов,  нарушением условий предоставления бюджетных инвестиций,  субсидий юридическим лицам,  индивидуальным предпринимателям и физическим лицам,  подлежат зачислению в бюджеты бюджетной системы Российской Федерации,  из которых были предоставлены соответствующие бюджетные средства,  бюджетные кредиты,  межбюджетные трансферты,  бюджетные инвестиции,  субсидии,  по нормативу 100 процентов.\n\n7. Суммы административных штрафов,  установленных законами субъектов Российской Федерации:\n\n1)  за нарушение законов и иных нормативных правовых актов субъектов Российской Федерации,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов;\n\n2)  за нарушение муниципальных правовых актов,  подлежат зачислению в бюджеты муниципальных образований по нормативу 100 процентов.\n\n8. В бюджеты субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя подлежат зачислению суммы административных штрафов,  подлежащие в соответствии с настоящей статьей зачислению в местные бюджеты и бюджеты субъектов Российской Федерации.\n\n9. Суммы штрафов (судебных штрафов) ,  установленных Уголовным кодексом Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n10. Суммы судебных штрафов (денежных взысканий) ,  налагаемых судами в случаях,  предусмотренных Арбитражным процессуальным кодексом Российской Федерации,  Гражданским процессуальным кодексом Российской Федерации,  Кодексом административного судопроизводства Российской Федерации,  Уголовно-процессуальным кодексом Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n11. Суммы штрафов,  пеней,  процентов,  установленных Налоговым кодексом Российской Федерации,  подлежат зачислению в бюджеты бюджетной системы Российской Федерации в следующем порядке:\n\n1)  суммы штрафов,  исчисляемых исходя из сумм (ставок)  налогов (сборов,  страховых взносов) ,  предусмотренных законодательством Российской Федерации о налогах и сборах,  - в бюджеты бюджетной системы Российской Федерации по нормативам отчислений,  установленным бюджетным законодательством Российской Федерации применительно к соответствующим налогам (сборам,  страховым взносам) ;\n\nсуммы пеней - в федеральный бюджет по нормативу 40 процентов,  в бюджет субъекта Российской Федерации по нормативу 43 процента с последующим распределением в текущем финансовом году Федеральным казначейством между бюджетами субъектов Российской Федерации в соответствии с федеральным законом о федеральном бюджете,  в бюджеты государственных внебюджетных фондов Российской Федерации по нормативу 17 процентов с последующим распределением в соответствии со статьей 146 настоящего Кодекса;\n\nсуммы процентов - в федеральный бюджет по нормативу 100 процентов;\n\n2)  суммы иных штрафов - в федеральный бюджет по нормативу 100 процентов.\n\n(Пункт в редакции  Федерального закона от 04.11.2022 № 432-ФЗ)\n\n12. Суммы штрафов,  пеней,  исчисляемых исходя из сумм страховых взносов на обязательное социальное страхование от несчастных случаев на производстве и профессиональных заболеваний,  взносов,  уплачиваемых организациями в соответствии с федеральными законами на выплату доплаты к пенсии,  подлежат зачислению в бюджеты государственных внебюджетных фондов Российской Федерации,  в которые зачисляются указанные взносы,  по нормативу 100 процентов.\n\n13. Пени и проценты,  установленные правом Евразийского экономического союза и (или)  законодательством Российской Федерации о таможенном регулировании,  начисленные на неуплаченные ввозные таможенные пошлины,  налоги,  антидемпинговые,  специальные и компенсационные пошлины,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  если иное не установлено правом Евразийского экономического союза.\n\n14. Пени и проценты,  установленные правом Евразийского экономического союза и (или)  законодательством Российской Федерации о таможенном регулировании,  начисленные на неуплаченные вывозные таможенные пошлины,  таможенные сборы,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n15. Пени,  установленные правом Евразийского экономического союза и (или)  законодательством Российской Федерации о таможенном регулировании,  начисленные на неуплаченные таможенные пошлины,  налоги,  взимаемые по единым ставкам,  таможенные пошлины,  налоги,  взимаемые в виде совокупного таможенного платежа,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\n16. Суммы штрафов,  неустоек,  пеней,  которые должны быть уплачены юридическим или физическим лицом в соответствии с законом или договором в случае неисполнения или ненадлежащего исполнения обязательств перед государственным (муниципальным)  органом,  государственным внебюджетным фондом,  казенным учреждением,  подлежат зачислению в бюджет бюджетной системы Российской Федерации,  получателем средств которого являются указанные орган,  учреждение,  по нормативу 100 процентов. (В редакции Федерального закона от 31.07.2020 № 263-ФЗ)\n\nСуммы штрафов,  неустоек,  пеней,  которые должны быть уплачены юридическим или физическим лицом в случае неисполнения или ненадлежащего исполнения поставщиком (подрядчиком,  исполнителем)  обязательств,  предусмотренных государственным контрактом,  заключенным государственной корпорацией,  публично-правовой компанией,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 01.07.2021 № 244-ФЗ)\n\n17. Денежные средства,  обращенные в собственность государства на основании обвинительных приговоров и постановлений судов,  вынесенных при производстве по уголовным делам,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  за исключением случаев,  установленных настоящим Кодексом. (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nДенежные средства,  изымаемые в собственность Российской Федерации,  субъектов Российской Федерации,  городских,  сельских поселений,  муниципальных районов,  муниципальных округов,  городских округов,  внутригородских территорий (внутригородских муниципальных образований)  городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  городских округов с внутригородским делением,  внутригородских районов в соответствии с решениями судов в случае,  не предусмотренном абзацем первым настоящего пункта,  подлежат зачислению соответственно в федеральный бюджет,  бюджеты субъектов Российской Федерации,  городских,  сельских поселений,  муниципальных районов,  муниципальных округов,  городских округов,  внутригородских территорий (внутригородских муниципальных образований)  городов федерального значения Москвы,  Санкт-Петербурга и Севастополя,  городских округов с внутригородским делением,  внутригородских районов по нормативу 100 процентов. (В редакции  федеральных законов от 01.10.2020 № 311-ФЗ,  от 13.07.2024 № 177-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 13.07.2024 № 177-ФЗ)\n\n18. Денежные средства,  полученные от реализации конфискованного имущества,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  если иное не установлено пунктами 17,  19 и 20 настоящей статьи.\n\n19. Денежные средства,  полученные от реализации конфискованных вещей,  явившихся орудиями совершения или предметами административных правонарушений,  обращенных в собственность субъектов Российской Федерации,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов.\n\n20. Денежные средства,  полученные от реализации конфискованных в установленном порядке орудий охоты,  рыболовства,  заготовки древесины (за исключением орудий,  изъятых в территориальном море,  на континентальном шельфе и в исключительной экономической зоне Российской Федерации)  и продукции незаконного природопользования,  подлежат зачислению по нормативу 100 процентов в бюджеты муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя по месту причинения вреда окружающей среде. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\n21. Платежи по искам о возмещении ущерба,  а также платежи,  уплачиваемые при добровольном возмещении ущерба,  причиненного государственному или муниципальному имуществу (за исключением имущества,  закрепленного за бюджетными (автономными)  учреждениями,  унитарными предприятиями) ,  подлежат зачислению в бюджеты публично-правовых образований,  в собственности которых находится указанное имущество,  по нормативу 100 процентов.\n\n22. Платежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде,  подлежат зачислению в бюджеты муниципальных районов,  муниципальных округов,  городских округов,  городских округов с внутригородским делением,  субъектов Российской Федерации - городов федерального значения Москвы,  Санкт-Петербурга и Севастополя по месту причинения вреда окружающей среде по нормативу 100 процентов,  если иное не установлено настоящим пунктом. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\nПлатежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде на особо охраняемых природных территориях федерального значения,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов.\n\nПлатежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде на особо охраняемых природных территориях регионального значения,  подлежат зачислению в бюджеты субъектов Российской Федерации по нормативу 100 процентов.\n\nПлатежи по искам о возмещении вреда,  причиненного окружающей среде,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного окружающей среде на особо охраняемых природных территориях местного значения,  подлежат зачислению в бюджеты муниципальных образований,  за счет которых осуществляются расходы,  связанные с охраной и использованием таких территорий,  по нормативу 100 процентов.\n\nПлатежи по искам о возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности Российской Федерации,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов,  если иное не установлено абзацами третьим и четвертым настоящего пункта. (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\nПлатежи по искам о возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности субъекта Российской Федерации или муниципального образования,  а также платежи,  уплачиваемые при добровольном возмещении вреда,  причиненного водным объектам,  водным биологическим ресурсам,  находящимся в собственности субъекта Российской Федерации или муниципального образования,  подлежат зачислению в бюджет соответствующего субъекта Российской Федерации или муниципального образования по нормативу 100 процентов. (Дополнение абзацем - Федеральный закон от 31.07.2020 № 263-ФЗ)  (В редакции  Федерального закона от 13.07.2024 № 177-ФЗ)\n\n23. Суммы штрафов,  уплачиваемых (взыскиваемых)  в соответствии с международными договорами Российской Федерации,  подлежат зачислению в федеральный бюджет по нормативу 100 процентов. (Дополнение пунктом - Федеральный закон от 01.07.2021 № 251-ФЗ)\n\n(Статья в редакции Федерального закона от 15.04.2019 № 62-ФЗ)","article_title":"Статья 47.2. Принятие решения о признании безнадежной к взысканию задолженности по платежам в бюджет и о ее списании (восстановлении)","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f2f782a82c3f26d83ad06a69c60d887916c497271bd8e2ec0a69fec6abc6497f"},{"code_id":"BK_RF","article_number":"48","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 48.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"49","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 20.08.2004 № 120-ФЗ)","article_title":"Статья 49.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d2fc6260056a24b700db74078d4fa449c90263cb9d2bbf7017daa88f1cfa4787"},{"code_id":"BK_RF","article_number":"5","version_date":"1998-07-31","article_text":"1. Закон (решение)  о бюджете вступает в силу с 1 января и действует по 31 декабря финансового года,  если иное не предусмотрено настоящим Кодексом и (или)  законом (решением)  о бюджете.\n\n2. Закон о бюджете подлежит официальному опубликованию не позднее пяти дней после его подписания в установленном порядке.\n\nРешение о бюджете подлежит официальному опубликованию не позднее 10 дней после его подписания в установленном порядке.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 5. Действие закона (решения)  о бюджете во времени","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6a7fa5eb5f1f518d13b8deb519a86750e33c07a5fcfbb98b2920c0eaa62373f3"}]$law7d0027$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
